/**
 * The switchboard's single data source.
 *
 * One scheduler polls NetSapiens v2 through the host proxy and every view reads
 * the result from context, so four modes and a dozen panels share one set of
 * requests instead of each polling on its own. Horizon apps have no push feed
 * for domain calls/queues/agents (see README "What needs NetSapiens"), so this
 * is the replacement for the Engage switchboard's socket:
 *
 *   job      every        request
 *   calls    4 s          GET /domains/:d/calls   (own calls below supervisor)
 *   queues   8 s          GET /domains/:d/callqueues   (live counts)
 *   queued   3 s tick     GET /domains/:d/queuedcall/:q  - only queues that have callers
 *   roster   3 s tick     GET /domains/:d/callqueues/:q/agents - stalest queue, one at a time
 *   agents   15 s         GET /domains/:d/agents   (one row per agent)
 *   users    20 s         GET /domains/:d/users
 *   parks    60 s         GET /domains/:d/callqueues?type=park
 *   vm       4 s tick     GET .../voicemails/new/count - one user at a time, while shown
 *   aas      5 min        GET /domains/:d/autoattendants - while shown
 *   config   once         portal configuration values
 *
 * An idle four-queue domain costs ~50 requests a minute against the proxy's
 * 100; the budget (api/budget.ts) defers background work before a click could
 * be refused. Polling pauses while the tab is hidden and catches up on return.
 * State is only replaced when a response actually differs, so an idle console
 * does not redraw on every poll.
 */
import type * as React from 'react';
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import type { HorizonApiClient } from '@netsapiens/horizon-sdk';
import { useHorizonContext } from '@netsapiens/horizon-sdk';

import type {
  AgentRow,
  AutoAttendantView,
  CallLeg,
  Contact,
  NsAgent,
  NsCallQueue,
  NsRecord,
  NsUser,
  Operator,
  ParkSlot,
  QueueView,
} from '../types';
import type { Capabilities } from '../model/capabilities';
import { BudgetExceeded, RequestBudget } from '../api/budget';
import * as ns from '../api/ns';
import { agentUser, buildAgentRows, toQueueMember } from '../model/agents';
import { linesFor, normaliseCalls, parkedCalls, placeholderCallers, queueCallers } from '../model/calls';
import { classifyError, describeReadError } from '../model/errors';
import { isParkQueue } from '../model/queues';
import { baseExtension, explicitNo, first, lower, parseSwitchTime, pick, toInt } from '../model/raw';
import { normFilterValue } from '../model/directory';
import { LIVE_SIGNAL_EVENT } from '../services/liveSignals';

export interface SwitchConfig {
  customStatuses: string[];
  crmLinkTemplate: string;
}

interface RosterState {
  rows: NsAgent[];
  error: string | null;
}

export type JobKey = 'config' | 'calls' | 'queues' | 'queued' | 'roster' | 'agents' | 'users' | 'parks' | 'vm' | 'aas';

export type WantKey = 'vm' | 'aas';

export interface SwitchboardData {
  domain: string;
  operator: Operator;
  caps: Capabilities;
  /** Use for clicks and panel reads (counted in the same budget as polling). */
  api: HorizonApiClient;
  /** Requests used in the last 60 s. */
  budgetUsed: () => number;
  /** When a job last succeeded (read on a clock tick; does not re-render). */
  lastOk: (key: JobKey) => number | null;
  loading: boolean;
  paused: boolean;
  /** Current read errors by job (null when healthy). */
  errors: Record<JobKey, string | null>;

  users: NsUser[];
  contacts: Contact[];
  contactsByUser: Map<string, Contact>;
  domainAgents: NsAgent[];
  /** The operator's own agent row in this domain, when they are one. */
  me: NsAgent | null;
  myQueues: string[];
  calls: CallLeg[];
  queues: QueueView[];
  parks: ParkSlot[];
  agentRows: AgentRow[];
  autoAttendants: AutoAttendantView[] | null;
  vmCounts: Record<string, number>;
  config: SwitchConfig;

  /** Run these jobs on the next tick regardless of interval. */
  refresh: (keys?: JobKey[]) => void;
  /** Re-read one queue roster now (after a write). */
  reloadRoster: (queue: string) => Promise<void>;
  /** Queue every roster for a re-read. */
  reloadAllRosters: () => void;
  /** Re-read one user's new-voicemail count now. */
  reloadVoicemailCount: (user: string) => Promise<void>;
  /** Views that need an on-demand dataset declare it while mounted. */
  want: (key: WantKey) => () => void;
}

const Ctx = createContext<SwitchboardData | null>(null);

export function useSwitchboard(): SwitchboardData {
  const v = useContext(Ctx);
  if (!v) throw new Error('useSwitchboard must be used inside SwitchboardDataProvider');
  return v;
}

/** Declare that the mounted view needs an on-demand dataset. */
export function useWant(key: WantKey, active = true): void {
  const { want } = useSwitchboard();
  useEffect(() => (active ? want(key) : undefined), [want, key, active]);
}

const INTERVAL: Record<JobKey, number> = {
  config: Number.POSITIVE_INFINITY,
  calls: 4000,
  queues: 8000,
  queued: 3000,
  roster: 3000,
  agents: 15000,
  users: 20000,
  parks: 60000,
  vm: 4000,
  aas: 300000,
};

const LABEL: Record<JobKey, string> = {
  config: 'configuration',
  calls: 'active calls',
  queues: 'call queues',
  queued: 'queued calls',
  roster: 'queue rosters',
  agents: 'agents',
  users: 'the company directory',
  parks: 'park slots',
  vm: 'voicemail counts',
  aas: 'auto attendants',
};

/** A queue roster is re-read when older than this (one queue per roster tick). */
const ROSTER_MAX_AGE = 20000;
/** A queue with callers is re-read at most this often. */
const QUEUED_MAX_AGE = 4000;
/** Queues read per queued tick. */
const QUEUED_PER_TICK = 2;
/** A user's new-voicemail count is re-read at most this often. */
const VM_MIN_AGE = 60000;

const ORDER: JobKey[] = ['config', 'calls', 'queues', 'users', 'agents', 'queued', 'roster', 'parks', 'aas', 'vm'];

function emptyErrors(): Record<JobKey, string | null> {
  const h = {} as Record<JobKey, string | null>;
  for (const k of ORDER) h[k] = null;
  return h;
}

interface JobState {
  lastRun: number;
  lastOk: number | null;
  running: boolean;
  failures: number;
}

function freshJobs(): Record<JobKey, JobState> {
  const js = {} as Record<JobKey, JobState>;
  for (const k of ORDER) js[k] = { lastRun: 0, lastOk: null, running: false, failures: 0 };
  return js;
}

interface Props {
  api: HorizonApiClient;
  domain: string;
  operator: Operator;
  caps: Capabilities;
  children: React.ReactNode;
}

export function SwitchboardDataProvider({ api, domain, operator, caps, children }: Props) {
  const budget = useMemo(() => new RequestBudget(api), [api]);
  const bg = budget.background;
  const fg = budget.foreground;

  const [users, setUsers] = useState<NsUser[] | null>(null);
  const [domainAgents, setDomainAgents] = useState<NsAgent[] | null>(null);
  const [callRows, setCallRows] = useState<NsRecord[] | null>(null);
  const [queueRows, setQueueRows] = useState<NsCallQueue[] | null>(null);
  const [parkRows, setParkRows] = useState<NsCallQueue[]>([]);
  const [rosters, setRosters] = useState<Record<string, RosterState>>({});
  const [queued, setQueued] = useState<Record<string, NsRecord[]>>({});
  const [aaRows, setAaRows] = useState<NsRecord[] | null>(null);
  const [vmCounts, setVmCounts] = useState<Record<string, number>>({});
  const [config, setConfig] = useState<SwitchConfig>({ customStatuses: [], crmLinkTemplate: '' });
  const [errors, setErrors] = useState<Record<JobKey, string | null>>(emptyErrors);
  const [paused, setPaused] = useState(false);

  // Refs the scheduler reads, so a tick never sees stale state.
  const epoch = useRef(0);
  const jobs = useRef<Record<JobKey, JobState>>(freshJobs());
  const errorsRef = useRef<Record<JobKey, string | null>>(emptyErrors());
  const forced = useRef(new Set<JobKey>());
  const wants = useRef(new Map<WantKey, number>());
  const sigs = useRef(new Map<string, string>());
  const queueRowsRef = useRef<NsCallQueue[]>([]);
  const parkRowsRef = useRef<NsCallQueue[]>([]);
  const callRowsRef = useRef<NsRecord[]>([]);
  const usersRef = useRef<NsUser[]>([]);
  const rosterAt = useRef(new Map<string, number>());
  const queuedAt = useRef(new Map<string, number>());
  const queuedHad = useRef(new Set<string>());
  const forcedRosters = useRef(new Set<string>());
  const vmCursor = useRef(0);
  const vmAt = useRef(new Map<string, number>());

  queueRowsRef.current = queueRows ?? [];
  parkRowsRef.current = parkRows;
  callRowsRef.current = callRows ?? [];
  usersRef.current = users ?? [];
  const peopleRef = useRef<NsUser[]>([]);

  /** True (and remembered) when `value` differs from the last one stored under `key`. */
  const changed = useCallback((key: string, value: unknown): boolean => {
    let s: string;
    try {
      s = JSON.stringify(value);
    } catch {
      return true;
    }
    if (sigs.current.get(key) === s) return false;
    sigs.current.set(key, s);
    return true;
  }, []);

  // Reset everything when the managed domain changes.
  useEffect(() => {
    epoch.current += 1;
    jobs.current = freshJobs();
    errorsRef.current = emptyErrors();
    forced.current.clear();
    sigs.current.clear();
    rosterAt.current.clear();
    queuedAt.current.clear();
    queuedHad.current.clear();
    forcedRosters.current.clear();
    vmCursor.current = 0;
    vmAt.current.clear();
    setUsers(null);
    setDomainAgents(null);
    setCallRows(null);
    setQueueRows(null);
    setParkRows([]);
    setRosters({});
    setQueued({});
    setAaRows(null);
    setVmCounts({});
    setErrors(emptyErrors());
  }, [domain]);

  const setError = useCallback((key: JobKey, msg: string | null) => {
    if (errorsRef.current[key] === msg) return;
    errorsRef.current = { ...errorsRef.current, [key]: msg };
    setErrors(errorsRef.current);
  }, []);

  // --- job bodies -----------------------------------------------------------

  const runners = useMemo(() => {
    const ext = operator.ext;
    const live = (e: number) => e === epoch.current;
    const rosterable = (): string[] => {
      const parks = new Set(parkRowsRef.current.map((p) => String(p.callqueue ?? '')));
      return queueRowsRef.current
        .filter((q) => q.callqueue && !parks.has(String(q.callqueue)) && !isParkQueue(String(q['callqueue-dispatch-type'] ?? '')))
        .map((q) => String(q.callqueue));
    };

    const r: Record<JobKey, (e: number) => Promise<void>> = {
      config: async (e) => {
        const [custom, crm] = await Promise.all([
          ns.readCustomStatuses(bg, domain).catch(() => [] as string[]),
          ns.readConfig(bg, 'PORTAL_ATTENDANT_STYLE_STATUS_MESSAGE', domain).catch(() => null),
        ]);
        if (live(e)) setConfig({ customStatuses: custom, crmLinkTemplate: crm ?? '' });
      },
      calls: async (e) => {
        let rows: NsRecord[] = [];
        if (caps.domainCalls) rows = await ns.readDomainCalls(bg, domain);
        else if (ext) rows = await ns.readUserCalls(bg, domain, ext);
        if (live(e) && changed('calls', rows)) setCallRows(rows);
      },
      queues: async (e) => {
        const rows = await ns.readCallQueues(bg, domain);
        if (live(e) && changed('queues', rows)) setQueueRows(rows);
      },
      parks: async (e) => {
        const rows = (await ns.readParkQueues(bg, domain)).filter((p) => p.callqueue);
        if (live(e) && changed('parks', rows)) setParkRows(rows);
      },
      users: async (e) => {
        const rows = (await ns.readUsers(bg, domain)).filter((u) => u.user);
        if (live(e) && changed('users', rows)) setUsers(rows);
      },
      agents: async (e) => {
        const rows = await ns.readDomainAgents(bg, domain);
        if (live(e) && changed('agents', rows)) setDomainAgents(rows);
      },
      roster: async (e) => {
        const exts = rosterable();
        let target = Array.from(forcedRosters.current).find((q) => exts.includes(q));
        if (!target) {
          const now = Date.now();
          let oldest = Number.POSITIVE_INFINITY;
          for (const q of exts) {
            const at = rosterAt.current.get(q) ?? 0;
            if (now - at >= ROSTER_MAX_AGE && at < oldest) {
              oldest = at;
              target = q;
            }
          }
        }
        if (!target) return;
        const q = target;
        forcedRosters.current.delete(q);
        rosterAt.current.set(q, Date.now());
        let next: RosterState;
        try {
          next = { rows: await ns.readQueueRoster(bg, domain, q), error: null };
        } catch (err) {
          if (err instanceof BudgetExceeded) {
            rosterAt.current.delete(q);
            throw err;
          }
          next = { rows: [], error: describeReadError('this queue roster', err) };
        }
        if (live(e) && changed(`roster:${q}`, next)) setRosters((prev) => ({ ...prev, [q]: next }));
      },
      queued: async (e) => {
        const now = Date.now();
        const throughs = new Set(
          callRowsRef.current
            .map((l) => baseExtension(pick(l, 'call-through-user', 'through-user', 'through_user', 'call-term-user')))
            .filter(Boolean),
        );
        const all = [...queueRowsRef.current, ...parkRowsRef.current];
        const counts = new Map(all.map((q) => [String(q.callqueue ?? ''), toInt(q['active-queued-calls-total-current'])] as const));
        const candidates = Array.from(counts.keys())
          .filter(Boolean)
          .filter((q) => (counts.get(q) ?? 0) > 0 || queuedHad.current.has(q) || throughs.has(q))
          .filter((q) => now - (queuedAt.current.get(q) ?? 0) >= QUEUED_MAX_AGE)
          .sort((a, b) => (queuedAt.current.get(a) ?? 0) - (queuedAt.current.get(b) ?? 0))
          .slice(0, QUEUED_PER_TICK);
        for (const q of candidates) {
          queuedAt.current.set(q, Date.now());
          let rows: NsRecord[] = [];
          try {
            rows = await ns.readQueuedCalls(bg, domain, q);
          } catch (err) {
            if (err instanceof BudgetExceeded) {
              queuedAt.current.delete(q);
              throw err;
            }
            // No queued-call detail for this queue: the calls feed still shows its callers.
          }
          if (!live(e)) return;
          if (rows.length) queuedHad.current.add(q);
          else queuedHad.current.delete(q);
          if (changed(`queued:${q}`, rows)) setQueued((prev) => ({ ...prev, [q]: rows }));
        }
      },
      vm: async (e) => {
        const list = peopleRef.current.filter(
          (u) => !explicitNo(u['voicemail-enabled']) && /^\d+$/.test(String(u.user ?? '')),
        );
        if (!list.length) return;
        const u = String(list[vmCursor.current % list.length].user);
        vmCursor.current += 1;
        // A small directory would otherwise re-read the same box every tick.
        if (Date.now() - (vmAt.current.get(u) ?? 0) < VM_MIN_AGE) return;
        vmAt.current.set(u, Date.now());
        const n = await ns.readVoicemailCount(bg, domain, u);
        if (live(e)) setVmCounts((prev) => (prev[u] === n ? prev : { ...prev, [u]: n }));
      },
      aas: async (e) => {
        let rows: NsRecord[];
        try {
          rows = await ns.readAutoAttendants(bg, domain);
        } catch (err) {
          if (err instanceof BudgetExceeded || !ext) throw err;
          const mine = await bg.get(`/domains/${encodeURIComponent(domain)}/users/${encodeURIComponent(ext)}/autoattendants`);
          rows = Array.isArray(mine) ? (mine as NsRecord[]) : [];
        }
        if (live(e) && changed('aas', rows)) setAaRows(rows);
      },
    };
    return r;
  }, [bg, caps.domainCalls, changed, domain, operator.ext]);

  // --- scheduler --------------------------------------------------------------

  useEffect(() => {
    let alive = true;
    const myEpoch = epoch.current;

    const enabled = (k: JobKey): boolean => {
      if (k === 'vm') return (wants.current.get('vm') ?? 0) > 0;
      if (k === 'aas') return (wants.current.get('aas') ?? 0) > 0;
      if (k === 'calls') return caps.domainCalls || !!operator.ext;
      return true;
    };

    const run = (k: JobKey) => {
      const st = jobs.current[k];
      st.running = true;
      st.lastRun = Date.now();
      forced.current.delete(k);
      runners[k](myEpoch)
        .then(() => {
          if (!alive || myEpoch !== epoch.current) return;
          st.failures = 0;
          st.lastOk = Date.now();
          setError(k, null);
        })
        .catch((err: unknown) => {
          if (!alive || myEpoch !== epoch.current) return;
          if (err instanceof BudgetExceeded) {
            st.lastRun = 0; // retry once the window has room
            return;
          }
          st.failures += 1;
          // A denied read will not start working on its own; stop hammering it.
          if (classifyError(err) === 'scope') st.failures = 8;
          setError(k, describeReadError(LABEL[k], err));
        })
        .finally(() => {
          st.running = false;
        });
    };

    const tick = () => {
      if (!alive || myEpoch !== epoch.current) return;
      if (typeof document !== 'undefined' && document.hidden) {
        setPaused(true);
        return;
      }
      setPaused(false);
      const now = Date.now();
      for (const k of ORDER) {
        const st = jobs.current[k];
        if (!st || st.running || !enabled(k)) continue;
        const interval = INTERVAL[k] * Math.min(2 ** st.failures, 8);
        const due = st.lastRun === 0 || forced.current.has(k) || (Number.isFinite(interval) && now - st.lastRun >= interval);
        if (!due) continue;
        if (!budget.canBackground(now)) break;
        run(k);
      }
    };

    const onVisible = () => {
      if (document.hidden) return;
      for (const k of ['calls', 'queues', 'users', 'agents'] as JobKey[]) forced.current.add(k);
      tick();
    };

    tick();
    const id = window.setInterval(tick, 1000);
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      alive = false;
      window.clearInterval(id);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [budget, caps.domainCalls, domain, operator.ext, runners, setError]);

  // A relayed host event (the operator's own call started/ended, a device or
  // registration change) pulls the next calls/queues poll forward, throttled.
  const { eventBus } = useHorizonContext();
  useEffect(() => {
    if (!eventBus) return undefined;
    let last = 0;
    const onSignal = () => {
      const now = Date.now();
      if (now - last < 1500) return;
      last = now;
      forced.current.add('calls');
      forced.current.add('queues');
    };
    eventBus.on(LIVE_SIGNAL_EVENT, onSignal);
    return () => eventBus.off(LIVE_SIGNAL_EVENT, onSignal);
  }, [eventBus]);

  // --- public actions -----------------------------------------------------------

  const refresh = useCallback((keys?: JobKey[]) => {
    const list = keys ?? (['calls', 'queues', 'users', 'agents', 'parks', 'queued'] as JobKey[]);
    for (const k of list) {
      forced.current.add(k);
      if (k === 'queued') queuedAt.current.clear();
    }
  }, []);

  const reloadRoster = useCallback(
    async (queue: string) => {
      const e = epoch.current;
      let next: RosterState;
      try {
        next = { rows: await ns.readQueueRoster(fg, domain, queue), error: null };
      } catch (err) {
        next = { rows: [], error: describeReadError('this queue roster', err) };
      }
      if (e !== epoch.current) return;
      rosterAt.current.set(queue, Date.now());
      sigs.current.set(`roster:${queue}`, JSON.stringify(next));
      setRosters((prev) => ({ ...prev, [queue]: next }));
      forced.current.add('agents');
      forced.current.add('queues');
    },
    [domain, fg],
  );

  const reloadAllRosters = useCallback(() => {
    for (const q of queueRowsRef.current) if (q.callqueue) forcedRosters.current.add(String(q.callqueue));
    forced.current.add('agents');
    forced.current.add('roster');
  }, []);

  const reloadVoicemailCount = useCallback(
    async (user: string) => {
      const e = epoch.current;
      try {
        const n = await ns.readVoicemailCount(fg, domain, user);
        if (e === epoch.current) setVmCounts((prev) => ({ ...prev, [user]: n }));
      } catch {
        /* the trickle will pick it up */
      }
    },
    [domain, fg],
  );

  const want = useCallback((key: WantKey) => {
    wants.current.set(key, (wants.current.get(key) ?? 0) + 1);
    forced.current.add(key);
    return () => {
      wants.current.set(key, Math.max(0, (wants.current.get(key) ?? 1) - 1));
    };
  }, []);

  const lastOk = useCallback((key: JobKey) => jobs.current[key]?.lastOk ?? null, []);
  const budgetUsed = useCallback(() => budget.used(), [budget]);

  // --- derived data ---------------------------------------------------------------

  const calls = useMemo(() => normaliseCalls(callRows ?? []), [callRows]);

  const agentByUser = useMemo(() => {
    const m = new Map<string, NsAgent>();
    for (const a of domainAgents ?? []) {
      const u = baseExtension(agentUser(a));
      if (u && !m.has(u)) m.set(u, a);
    }
    return m;
  }, [domainAgents]);

  // NetSapiens lists queues, park orbits, auto attendants and sites as users
  // too. They are not people, so they stay off the Contacts board and out of
  // the staffing lists (the lab's Billing queue is user 4002 "Billing Queue").
  const systemExts = useMemo(() => {
    const s = new Set<string>(['domain']);
    for (const q of queueRows ?? []) if (q.callqueue) s.add(String(q.callqueue));
    for (const p of parkRows) if (p.callqueue) s.add(String(p.callqueue));
    for (const a of aaRows ?? []) {
      const ext = pick(a, 'user', 'auto-attendant');
      if (ext) s.add(ext);
    }
    return s;
  }, [aaRows, parkRows, queueRows]);

  const people = useMemo(
    () =>
      (users ?? []).filter((u) => {
        const id = String(u.user ?? '');
        if (!id || systemExts.has(id)) return false;
        return !(lower(u['user-scope']) === 'no portal' && !/^\d+$/.test(id));
      }),
    [systemExts, users],
  );

  const contacts = useMemo<Contact[]>(
    () =>
      people.map((u) => {
        const user = String(u.user ?? '');
        const firstName = String(u['name-first-name'] ?? '').trim();
        const lastName = String(u['name-last-name'] ?? '').trim();
        const presence = lower(u['user-presence-status']);
        const agent = agentByUser.get(user) ?? null;
        const lines = linesFor(calls, user);
        const queueList = String(agent?.queue_list ?? agent?.callqueue ?? '')
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean);
        return {
          user,
          firstName,
          lastName,
          name: `${firstName} ${lastName}`.trim() || user,
          site: normFilterValue(u.site),
          department: normFilterValue(u.department),
          presence,
          dnd: presence === 'dnd',
          portalStatus: first(u['status-message'], u.portal_status, agent?.['agent-status-message'], agent?.['status-message']),
          lastUpdate: parseSwitchTime(u['last-modified-datetime']) ?? parseSwitchTime(agent?.['last-modified-datetime']),
          scope: String(u['user-scope'] ?? ''),
          voicemailEnabled: !explicitNo(u['voicemail-enabled']),
          lines,
          isOnCall: lines.length > 0 || toInt(u['active-calls-total-current']) > 0,
          agent,
          queues: queueList,
          raw: u,
        };
      }),
    [agentByUser, calls, people],
  );

  peopleRef.current = people;
  const contactsByUser = useMemo(() => new Map(contacts.map((c) => [c.user, c] as const)), [contacts]);

  const parkExts = useMemo(() => {
    const s = new Set<string>();
    for (const p of parkRows) if (p.callqueue) s.add(String(p.callqueue));
    for (const q of queueRows ?? []) {
      if (q.callqueue && isParkQueue(String(q['callqueue-dispatch-type'] ?? ''))) s.add(String(q.callqueue));
    }
    return s;
  }, [parkRows, queueRows]);

  const queues = useMemo<QueueView[]>(() => {
    const nameOf = (u: string) => contactsByUser.get(u)?.name;
    return (queueRows ?? [])
      .filter((q) => q.callqueue && !parkExts.has(String(q.callqueue)))
      .map((q) => {
        const ext = String(q.callqueue);
        const roster = rosters[ext];
        const members = roster ? roster.rows.map((a) => toQueueMember(a, ext, nameOf(agentUser(a)))) : null;
        const { waiting, active } = queueCallers(ext, queued[ext], calls);
        const reportedWaiting = toInt(q['active-queued-calls-total-current']);
        const description = String(q.description ?? '').trim();
        const view: QueueView = {
          ext,
          name: description || ext,
          description,
          site: normFilterValue(q.site),
          department: normFilterValue(first(q.subscriber_group, q['subscriber-group'], q.group)),
          dispatchType: String(q['callqueue-dispatch-type'] ?? ''),
          isPark: false,
          reportedWaiting,
          agentsAvailable: toInt(q['callqueue-count-agents-available']),
          agentsTotal: toInt(q['callqueue-count-agents-total']),
          agentsLoggedIn: toInt(q.agent_loggedin_count),
          waiting: waiting.length ? waiting : placeholderCallers(ext, reportedWaiting),
          active,
          roster: members,
          rosterLoadedAt: roster ? rosterAt.current.get(ext) ?? null : null,
          rosterError: roster?.error ?? null,
          raw: q,
        };
        return view;
      });
  }, [calls, contactsByUser, parkExts, queueRows, queued, rosters]);

  const parks = useMemo<ParkSlot[]>(() => {
    const rows = new Map<string, NsCallQueue>();
    for (const p of parkRows) if (p.callqueue) rows.set(String(p.callqueue), p);
    for (const q of queueRows ?? []) {
      const ext = String(q.callqueue ?? '');
      if (ext && parkExts.has(ext) && !rows.has(ext)) rows.set(ext, q);
    }
    return Array.from(rows.values())
      .map((p) => {
        const ext = String(p.callqueue);
        return {
          ext,
          name: String(p.description ?? '').replace(/["']/g, '').trim(),
          site: normFilterValue(p.site),
          calls: parkedCalls(ext, queued[ext], calls),
          reportedCount: toInt(p['active-queued-calls-total-current']),
        };
      })
      .sort((a, b) => a.ext.localeCompare(b.ext, undefined, { numeric: true }));
  }, [calls, parkExts, parkRows, queueRows, queued]);

  const agentRows = useMemo(
    () => buildAgentRows(queues, domainAgents ?? [], contactsByUser),
    [contactsByUser, domainAgents, queues],
  );

  const me = useMemo(() => (operator.ext ? agentByUser.get(operator.ext) ?? null : null), [agentByUser, operator.ext]);

  const myQueues = useMemo(() => {
    if (!operator.ext) return [] as string[];
    const s = new Set<string>();
    for (const q of queues) if (q.roster?.some((m) => baseExtension(m.user) === operator.ext)) s.add(q.ext);
    for (const q of String(me?.queue_list ?? me?.callqueue ?? '').split(',')) {
      if (q.trim()) s.add(q.trim());
    }
    return Array.from(s);
  }, [me, operator.ext, queues]);

  const autoAttendants = useMemo<AutoAttendantView[] | null>(() => {
    if (!aaRows) return null;
    return aaRows.map((r, i) => {
      const ext = pick(r, 'user', 'auto-attendant', 'id') || String(i + 1);
      const name = first(r['attendant-name'], r.description, r['auto-attendant-description'], r['auto-attendant-name'], r.name, ext);
      const optionCount = Array.isArray(r.options) ? r.options.length : Array.isArray(r.timeframes) ? r.timeframes.length : 0;
      return {
        id: pick(r, 'id', 'auto-attendant') || ext,
        ext,
        name,
        displayName: name === ext ? `AA ${ext}` : name,
        optionCount,
        raw: r,
      };
    });
  }, [aaRows]);

  // Loading means "the first answer has not arrived", not "no data": a read the
  // switch refuses leaves its rows null for good, and a spinner that waits on
  // it hides the very message that explains why (masquerade into a domain the
  // user cannot read showed nothing but "Connecting").
  const loading =
    (users === null && !errors.users) ||
    (queueRows === null && !errors.queues) ||
    (callRows === null && !errors.calls && (caps.domainCalls || !!operator.ext));

  const value = useMemo<SwitchboardData>(
    () => ({
      domain,
      operator,
      caps,
      api: fg,
      budgetUsed,
      lastOk,
      loading,
      paused,
      errors,
      users: users ?? [],
      contacts,
      contactsByUser,
      domainAgents: domainAgents ?? [],
      me,
      myQueues,
      calls,
      queues,
      parks,
      agentRows,
      autoAttendants,
      vmCounts,
      config,
      refresh,
      reloadRoster,
      reloadAllRosters,
      reloadVoicemailCount,
      want,
    }),
    [
      agentRows,
      autoAttendants,
      budgetUsed,
      calls,
      caps,
      config,
      contacts,
      contactsByUser,
      domain,
      domainAgents,
      errors,
      fg,
      lastOk,
      loading,
      me,
      myQueues,
      operator,
      parks,
      paused,
      queues,
      refresh,
      reloadAllRosters,
      reloadRoster,
      reloadVoicemailCount,
      users,
      vmCounts,
      want,
    ],
  );

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}
